const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");

const root = "/Users/lyston/raap";
const preferredBranches = [
  "feature/raap_v2",
  "raap_v2",
  "v2",
  "feature/v2",
  "raap_next",
];

function run(repo, args) {
  return execFileSync("git", ["-C", repo, ...args], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  }).trim();
}

function runVisible(repo, args) {
  return execFileSync("git", ["-C", repo, ...args], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  }).trim();
}

const repos = fs
  .readdirSync(root, { withFileTypes: true })
  .filter((entry) => entry.isDirectory())
  .map((entry) => path.join(root, entry.name))
  .filter((dir) => fs.existsSync(path.join(dir, ".git")))
  .sort();

for (const repo of repos) {
  const name = path.basename(repo);
  const dirty = run(repo, ["status", "--porcelain=v1"]);
  if (dirty) {
    console.log(`${name}\tSKIP dirty worktree`);
    continue;
  }

  const beforeBranch = run(repo, ["branch", "--show-current"]) || "(detached)";
  const beforeHead = run(repo, ["rev-parse", "--short", "HEAD"]);
  run(repo, ["fetch", "--prune", "origin"]);

  const remoteBranches = new Set(
    run(repo, ["branch", "-r"])
      .split("\n")
      .map((line) => line.trim().replace(/^origin\//, ""))
      .filter(Boolean),
  );

  const selected =
    preferredBranches.find((branch) => remoteBranches.has(branch)) ||
    (beforeBranch !== "(detached)" ? beforeBranch : null);

  if (!selected) {
    console.log(`${name}\tSKIP no branch\tbefore=${beforeBranch}@${beforeHead}`);
    continue;
  }

  const localBranches = new Set(
    run(repo, ["branch", "--format=%(refname:short)"])
      .split("\n")
      .map((line) => line.trim())
      .filter(Boolean),
  );

  if (localBranches.has(selected)) {
    run(repo, ["checkout", selected]);
  } else {
    run(repo, ["checkout", "-b", selected, `origin/${selected}`]);
  }

  let pullOutput = "";
  try {
    pullOutput = runVisible(repo, ["pull", "--ff-only", "origin", selected]);
  } catch (error) {
    console.log(`${name}\tPULL_FAILED branch=${selected}\t${String(error.stderr || error.message).trim()}`);
    continue;
  }

  const afterHead = run(repo, ["rev-parse", "--short", "HEAD"]);
  console.log(`${name}\t${beforeBranch}@${beforeHead} -> ${selected}@${afterHead}\t${pullOutput || "updated"}`);
}

