    .replace(/\bsk-[A-Za-z0-9_-]{20,}\b/g, "CHANGE_ME_API_KEY")
    .replace(/\bAIza[0-9A-Za-z_-]{20,}\b/g, "CHANGE_ME_API_KEY");

