    .replace(/(\b(?:mysqlPassword|redisPassword|rootPassword|password|MYSQL_ANALYTICS_PASSWORD|SRC_PASSWORD|DST_PASSWORD)\s*[:=]\s*)(["'])(?!CHANGE_ME|YOUR_|your_|\$\{|\{\{)([^"'\n#]*[!@#$%^&*()_+=.,;:/?-][^"'\n]*)(["'])/gi, "$1$2CHANGE_ME_PASSWORD$4")
    .replace(/(\b(?:MYSQL_ROOT_PASSWORD|MYSQL_PASSWORD|REDIS_PASSWORD|POSTGRES_PASSWORD|PGADMIN_DEFAULT_PASSWORD|MEM0_PG_PASSWORD)\s*[:=]\s*)(["']?)(?!CHANGE_ME|YOUR_|your_|\$\{|\{\{)([^\s"'\n#;&|]{4,})(["']?)/g, "$1$2CHANGE_ME_PASSWORD$4")
    .replace(/(\b(?:REDASH_API_KEY|AIHUBMIX_API_KEY|OPENAI_API_KEY|GEMINI_API_KEY|DEEPSEEK_API_KEY)\s*[:=]\s*)(["']?)(?!CHANGE_ME|YOUR_|your_|\$\{|\{\{)([^\s"'\n#;&|]{6,})(["']?)/g, "$1$2CHANGE_ME_API_KEY$4")
    .replace(/\$\{MYSQL_ROOT_PASSWORD:-[^}]+\}/g, "${MYSQL_ROOT_PASSWORD:-CHANGE_ME_PASSWORD}")
    .replace(/\$\{MYSQL_PASSWORD:-[^}]+\}/g, "${MYSQL_PASSWORD:-CHANGE_ME_PASSWORD}")
    .replace(/\$\{REDIS_PASSWORD:-[^}]+\}/g, "${REDIS_PASSWORD:-CHANGE_ME_PASSWORD}")
    .replace(/mysql_password=\$\{mysql_password:-"[^"]+"\}/g, 'mysql_password=${mysql_password:-"CHANGE_ME_PASSWORD"}')
    .replace(/redis_password=\$\{redis_password:-"[^"]+"\}/g, 'redis_password=${redis_password:-"CHANGE_ME_PASSWORD"}')
    .replace(/Password:\s*[^\s"`']{4,}/g, "Password: CHANGE_ME_PASSWORD")
    .replace(/password="[^"]{4,}"/g, 'password="CHANGE_ME_PASSWORD"')
    .replace(/password='[^']{4,}'/g, "password='CHANGE_ME_PASSWORD'");

  if (text !== original) {
    fs.writeFileSync(file, text);
    return true;
